  if (summary.folders.length > 0) {
    lines.push(sectionHeader("Folders", '--folder-path "<path>"  or  --folder-key <key>'), ...summary.folders.map(formatFolderRow));
  }
  if (summary.personalWorkspace.length > 0) {
    lines.push(sectionHeader("Personal workspace", "--personal-workspace"), ...summary.personalWorkspace.map(formatFeedRow));
  }
  if (summary.sharedLibraries.length > 0) {
    lines.push(sectionHeader("Shared libraries", '--shared-libraries  [--folder-key <key> | --folder-path "<path>"]'), ...summary.sharedLibraries.map(formatFeedRow));
  }
  if (summary.feeds.length > 0) {
    lines.push(sectionHeader("Feeds", "--feed-id <id>"), ...summary.feeds.map(formatFeedRow));
  }
