        accessToken: status.accessToken,
        baseUrl,
        organizationId: orgId,
        organizationName: status.organizationName ?? "",
        tenantId: status.tenantId ?? "",
        tenantName,
        serviceUrls,
        orgScopedServices: ORG_SCOPED_SERVICES
