// src/resolution/compatibility.ts
var MIN_STUDIO_VERSION = "26.0.191";

class StudioUpgradeRequiredError extends Error {
  constructor(detectedVersion) {
    super(`Requires Studio ${MIN_STUDIO_VERSION}+, detected ${detectedVersion}. ` + "Please upgrade UiPath Studio.");
  }
}
function compareManifests(expected, actual, detectedVersion) {
  const missingEndpoints = [];
  const missingMethods = {};
  let totalExpected = 0;
  let totalMissing = 0;
  for (const [endpoint, methods] of Object.entries(expected.endpoints)) {
    totalExpected += methods.length;
    const actualMethods = actual.endpoints[endpoint];
    if (!actualMethods) {
      missingEndpoints.push(endpoint);
      totalMissing += methods.length;
      continue;
    }
    const actualMethodSet = new Set(actualMethods);
    const missing = methods.filter((m) => !actualMethodSet.has(m));
    if (missing.length > 0) {
      missingMethods[endpoint] = missing;
      totalMissing += missing.length;
    }
  }
  if (totalMissing === 0) {
    return { status: "full" };
  }
  const coverage = 1 - totalMissing / totalExpected;
  if (coverage < 0.5) {
    return { status: "incompatible", detectedVersion };
  }
  return { status: "partial", missingEndpoints, missingMethods };
}
function checkCompatibility(binDir, deps) {
  const studioManifest = readInteropManifest(binDir, deps);
  if (!studioManifest) {
    const detectedVersion = getStudioFileVersion(binDir, deps);
    return { status: "incompatible", detectedVersion };
  }
  return compareManifests(interop_manifest_default, studioManifest, getStudioFileVersion(binDir, deps));
}
function enforce(result, label, incompatibleMessage, deps) {
  switch (result.status) {
    case "incompatible":
      throw new Error(incompatibleMessage);
    case "partial": {
      const details = [
        ...result.missingEndpoints.map((e) => `  - ${e} (entire service)`),
        ...Object.entries(result.missingMethods).map(([ep, methods]) => `  - ${ep}: ${methods.join(", ")}`)
      ].join(`
`);
      deps.log(`Partial ${label} compatibility — some features may not work:
${details}`);
      break;
    }
    case "full":
      break;
  }
}
function enforceCompatibility(binDir, deps) {
  const result = checkCompatibility(binDir, deps);
  enforce(result, "Studio", new StudioUpgradeRequiredError(result.status === "incompatible" ? result.detectedVersion : "unknown").message, deps);
}

