// src/commands/start-studio.ts
function registerStartStudioCommand(program4, options) {
  const description = "Start a Studio instance and wait until it is ready. Additional commands may become available once Studio is running.";
  const action = async () => {
    if (!options) {
      throw new Error("Cannot start Studio without project context. Provide --project-dir.");
    }
    const deps = options.verbose ? {
      ...defaultResolverDeps,
      log: (msg) => console.debug(`[rpa-tool] ${msg}`)
    } : defaultResolverDeps;
    const timeoutMs = options.timeoutSeconds != null ? options.timeoutSeconds * 1000 : undefined;
    const session = new StudioSession({
      projectDir: options.projectDir,
      studioBinDir: options.studioDir,
      timeoutMs
    }, deps);
    const instance = await session.execute(async (inst) => inst, {
      requiresProject: false
    });
    console.log(`Studio instance ready (PID ${instance.processId}).`);
  };
  const studioGroup = program4.command("studio").description("Control the Studio process");
  studioGroup.command("start").description(description).trackedAction(processContext, action);
  program4.command("start-studio", { hidden: true }).description(description).trackedAction(processContext, action);
}

