// src/tools/IpcToolProvider.ts
class IpcToolProvider {
  pipeName;
  timeoutMs;
  knownToolNames = null;
  constructor(pipeName, timeoutMs) {
    this.pipeName = pipeName;
    this.timeoutMs = timeoutMs;
  }
  async listTools() {
    try {
      const json3 = await callListTools(this.pipeName, this.timeoutMs);
      const tools = JSON.parse(json3);
      this.knownToolNames = new Set(tools.map((t2) => t2.name));
      return tools;
    } finally {
      await disposeIpcConnections();
    }
  }
  async callTool(name, args, projectDir) {
    if (this.knownToolNames && !this.knownToolNames.has(name)) {
      return;
    }
    try {
      const json3 = await callCallTool(this.pipeName, name, JSON.stringify(args), projectDir ?? null, this.timeoutMs);
      return JSON.parse(json3);
    } finally {
      await disposeIpcConnections();
    }
  }
}

// src/tools/LocalToolProvider.ts
function createToolHandler(session, definition, execute) {
  const scoped = session.forTool?.(definition.name) ?? session;
  return {
    definition,
    execute: (args, projectDir) => execute(scoped, args, projectDir)
  };
}

class LocalToolProvider {
  handlers = new Map;
  register(handler) {
    this.handlers.set(handler.definition.name, handler);
  }
  async listTools() {
    return [...this.handlers.values()].map((h) => h.definition);
  }
  async callTool(name, args, projectDir) {
    const handler = this.handlers.get(name);
    if (!handler)
      return;
    return handler.execute(args, projectDir);
  }
}

