// src/tools/local/get-errors.ts
import { existsSync as existsSync12 } from "node:fs";
import { isAbsolute as isAbsolute11, resolve as resolve13 } from "node:path";
var SEVERITIES = ["error", "warning", "info", "verbose"];
var LEVEL_BY_NAME = Object.fromEntries(SEVERITIES.map((name, i3) => [name, i3 + 1]));
var NAME_BY_LEVEL = Object.fromEntries(SEVERITIES.map((name, i3) => [i3 + 1, name]));
function parseDiagnostic(json4) {
  try {
    const raw = JSON.parse(json4);
    const severity = NAME_BY_LEVEL[raw.severity];
    if (!severity) {
      return null;
    }
    const details = raw.errorDetails;
    const activityId = details?.activityId?.idRef || details?.activityId?.id;
    return {
      severity,
      file: raw.file ?? "Unknown",
      description: raw.description ?? json4,
      code: raw.code,
      ruleName: raw.ruleName,
      activityId,
      documentationLink: details?.documentationLink
    };
  } catch {
    return null;
  }
}
function formatLine(d) {
  const meta = [d.code, d.ruleName].filter(Boolean).join(", ");
  const suffix = meta ? ` (${meta})` : "";
  const location = d.activityId ? ` | activity: ${d.activityId}` : "";
  const docs = d.documentationLink ? ` | docs: ${d.documentationLink}` : "";
  return `[${d.severity}] ${d.file} - ${d.description}${suffix}${location}${docs}`;
}
function formatDiagnostics(diagnostics, minSeverity, unparseableCount) {
  const threshold = LEVEL_BY_NAME[minSeverity] ?? LEVEL_BY_NAME.warning;
  const visible = diagnostics.filter((diagnostic) => LEVEL_BY_NAME[diagnostic.severity] <= threshold).sort((a, b) => LEVEL_BY_NAME[a.severity] - LEVEL_BY_NAME[b.severity]);
  if (visible.length === 0 && unparseableCount === 0) {
    return "No diagnostics found.";
  }
  const counts = SEVERITIES.filter((name) => LEVEL_BY_NAME[name] <= threshold).map((name) => {
    const numVisible = visible.filter((diagnostic) => diagnostic.severity === name).length;
    return numVisible > 0 ? `${numVisible} ${name}(s)` : null;
  }).filter(Boolean).join(", ");
  const lines = visible.map(formatLine);
  const parts = counts ? [`Found ${counts}:`, ...lines] : [...lines];
  if (unparseableCount > 0) {
    parts.push(`(${unparseableCount} diagnostic(s) could not be parsed)`);
  }
  return parts.join(`
`);
}
function resolveTargetedFile(filePath, projectDir) {
  if (!filePath) {
    return;
  }
  if (isAbsolute11(filePath)) {
    return filePath;
  }
  return projectDir !== undefined ? resolve13(projectDir, filePath) : undefined;
}
function getErrorsTool(session) {
  return createToolHandler(session, {
    name: ToolName.GetErrors,
    title: "Get Errors",
    description: "Validate a single file or the entire project and return diagnostics, " + "filtered by severity. If filePath is omitted, scopes to the whole project. " + "By default, runs validation before returning diagnostics; set skipValidation " + "to true to read the cached results from the last validation. " + "Use minSeverity 'error' for quick checks; 'warning' (default) or 'info' for thorough reviews.",
    requiresProject: true,
    inputSchema: {
      type: "object",
      properties: {
        filePath: {
          type: "string",
          description: "The relative path of the file to get errors for (relative to the project directory). " + "If omitted, retrieves errors for the entire project."
        },
        skipValidation: {
          type: "boolean",
          description: "If true, skips validation and returns cached errors currently shown in the designer (from last validation), which might be stale. " + "If false (default), forces Studio to run validation before retrieving errors.",
          default: false
        },
        minSeverity: {
          type: "string",
          enum: ["error", "warning", "info", "verbose"],
          description: "The minimum severity level of diagnostics to include. " + "'error' returns only errors, 'warning' includes errors and warnings, " + "'info' adds informational messages, 'verbose' returns everything. " + "Defaults to 'warning'.",
          default: "warning"
        }
      }
    }
  }, async (session2, args, projectDir) => {
    const filePath = args.filePath;
    const skipValidation = args.skipValidation ?? false;
    const minSeverity = args.minSeverity ?? "warning";
    const resolvedPath = resolveTargetedFile(filePath, projectDir);
    if (resolvedPath !== undefined && !existsSync12(resolvedPath)) {
      return {
        content: [
          {
            type: "text",
            text: JSON.stringify({
              success: false,
              errorMessage: `Cannot validate '${filePath}': file not found at '${resolvedPath}'. ` + "--file-path must name an existing file. If relative, it is resolved against the project directory."
            })
          }
        ],
        isError: true
      };
    }
    try {
      const rawDiagnostics = await session2.execute(async (instance) => {
        if (instance.backendType === "Helm" /* Helm */) {
          return filePath ? instance.helmServices.validation.validateFile(filePath) : instance.helmServices.validation.validateProject();
        }
        if (!skipValidation) {
          return filePath ? instance.services.error.validateFile(filePath) : instance.services.error.validateProject();
        }
        return filePath ? instance.services.error.getFileErrors(filePath) : instance.services.error.getProjectErrors();
      }, { requiresProject: true, backend: "helm" /* Helm */ });
      const parsed = rawDiagnostics.map(parseDiagnostic);
      const diagnostics = parsed.filter((d) => d !== null);
      const unparseableCount = parsed.length - diagnostics.length;
      return {
        content: [
          {
            type: "text",
            text: formatDiagnostics(diagnostics, minSeverity, unparseableCount)
          }
        ]
      };
    } catch (e) {
      const errorMessage3 = e instanceof Error ? e.message : String(e);
      console.error(`[get-errors] error:`, errorMessage3);
      return {
        content: [
          {
            type: "text",
            text: JSON.stringify({
              success: false,
              errorMessage: errorMessage3
            })
          }
        ],
        isError: true
      };
    }
  });
}

