// src/tools/common/workflow-examples-api.ts
var AGENTIC_LOOP_PATH = "autopilotstudio_/autopilot-everywhere";
var CONTAINER_NAME = "rpa-workflow-demos";

// src/tools/local/get-workflow-example.ts
function getWorkflowExampleTool(client) {
  return {
    definition: {
      name: ToolName.GetWorkflowExample,
      title: "Get Workflow Example",
      description: "Get the XAML content of a specific RPA workflow example. " + "Use a key obtained from `workflow-examples list` to fetch the actual workflow content.",
      requiresProject: false,
      inputSchema: {
        type: "object",
        properties: {
          key: {
            type: "string",
            description: "The blob key/path of the example workflow to retrieve. " + "Should be a key returned from list-workflow-examples. " + 'Example: "email-automation/add-new-gmail-emails-to-keap-as-contacts.xaml"'
          }
        },
        required: ["key"]
      }
    },
    async execute(args) {
      const key = args.key;
      if (!key || key.trim().length === 0) {
        return {
          content: [
            {
              type: "text",
              text: JSON.stringify({
                success: false,
                errorMessage: "Key cannot be empty."
              })
            }
          ],
          isError: true
        };
      }
      try {
        const content = await client.get(`${AGENTIC_LOOP_PATH}/v1/blobs/${CONTAINER_NAME}/${encodeURIComponent(key)}`);
        if (!content || typeof content === "string" && content.length === 0) {
          return {
            content: [
              {
                type: "text",
                text: `No content found for key: ${key}`
              }
            ]
          };
        }
        return {
          content: [
            {
              type: "text",
              text: JSON.stringify({
                key,
                content: typeof content === "string" ? content : JSON.stringify(content)
              }, null, 2)
            }
          ]
        };
      } catch (e) {
        const errorMessage3 = e instanceof Error ? e.message : String(e);
        console.error(`[get-workflow-example] error:`, errorMessage3);
        return {
          content: [
            {
              type: "text",
              text: JSON.stringify({
                success: false,
                errorMessage: errorMessage3
              })
            }
          ],
          isError: true
        };
      }
    }
  };
}

