function normalizePackages(raw) {
  const arr = typeof raw === "string" ? JSON.parse(raw) : raw;
  if (!Array.isArray(arr) || arr.length === 0) {
    return [];
  }
  return arr.map((p) => {
    const entry = {
      Id: p.id ?? p.Id
    };
    const version = p.version ?? p.Version;
    if (version) {
      entry.Version = version;
    }
    return entry;
  });
}
