// src/tools/local/list-workflow-examples.ts
function listWorkflowExamplesTool(client) {
  return {
    definition: {
      name: ToolName.ListWorkflowExamples,
      title: "List Workflow Examples",
      description: "List RPA workflow examples, optionally narrowed by service tags " + "(e.g. confluence, jira, salesforce, outlook, gmail, slack) or by path " + "prefix. With no filters it returns the first `limit` examples in the " + "catalogue. Each match can be retrieved by key via `workflow-examples get`.",
      requiresProject: false,
      inputSchema: {
        type: "object",
        properties: {
          tags: {
            type: "array",
            items: { type: "string" },
            description: "Service tags to filter examples by; omit to list without a tag filter. " + 'Use lowercase service names, e.g. ["web"] or ["confluence"] or ["salesforce", "outlook"].' + "The more tags provided, the more narrowed-down the search results will be (AND logic)."
          },
          prefix: {
            type: "string",
            description: "Optional path prefix to filter examples by location. " + "For example, use prefix 'document-processing/' or 'web-api-automation/' or 'cloud-storage/' for targeted searches."
          },
          limit: {
            type: "integer",
            description: "Maximum number of examples to return. Defaults to 10, max 100.",
            default: 10
          }
        }
      }
    },
    async execute(args) {
      const tags = args.tags ?? [];
      const prefix = args.prefix;
      const limit = args.limit || 10;
      try {
        const params = buildSearchQueryParams(tags, prefix, limit);
        const response = await client.get(`${AGENTIC_LOOP_PATH}/v1/blobs/${CONTAINER_NAME}?${params}`);
        if (!response.items || response.items.length === 0) {
          return {
            content: [
              {
                type: "text",
                text: `No workflow examples found${describeFilters(tags, prefix)}`
              }
            ]
          };
        }
        const examples = response.items.map((item) => ({
          key: item.key,
          tags: item.tags ? Object.keys(item.tags) : []
        }));
        return {
          content: [
            {
              type: "text",
              text: JSON.stringify({
                total: response.total,
                tags: tags.join(", "),
                examples
              }, null, 2)
            }
          ]
        };
      } catch (e) {
        const errorMessage3 = e instanceof Error ? e.message : String(e);
        console.error(`[list-workflow-examples] error:`, errorMessage3);
        return {
          content: [
            {
              type: "text",
              text: JSON.stringify({
                success: false,
                errorMessage: errorMessage3
              })
            }
          ],
          isError: true
        };
      }
    }
  };
}
function describeFilters(tags, prefix) {
  const filters = [
    tags.length > 0 ? `tags: ${tags.join(", ")}` : null,
    prefix ? `prefix: ${prefix}` : null
  ].filter((filter) => filter !== null);
  return filters.length > 0 ? ` for ${filters.join(", ")}` : ".";
}
function buildSearchQueryParams(tags, prefix, limit) {
  const params = new URLSearchParams;
  for (const tag of tags) {
    params.append(`tag_${tag}`, "true");
  }
  prefix && params.append("prefix", prefix);
  limit && params.append("limit", String(limit));
  return params.toString();
}

