// src/tools/ResolvingToolProvider.ts
class ResolvingToolProvider {
  localToolSource;
  session;
  projectDir;
  providerFactory;
  constructor(localToolSource, session, projectDir, providerFactory = (pipe) => new IpcToolProvider(pipe)) {
    this.localToolSource = localToolSource;
    this.session = session;
    this.projectDir = projectDir;
    this.providerFactory = providerFactory;
  }
  async listTools() {
    const localTools = await this.localToolSource.listTools();
    const localNames = new Set(localTools.map((t2) => t2.name));
    try {
      const studioTools = await this.session.execute(async (instance) => {
        const provider = this.providerFactory(instance.ipcEndpointName);
        return provider.listTools();
      }, { requiresProject: false, discoveryOnly: true });
      const additionalTools = studioTools.filter((t2) => !localNames.has(t2.name));
      return [...localTools, ...additionalTools];
    } catch {
      this.session.log("No reachable Studio instance for tool discovery, using local tools only");
      return localTools;
    }
  }
  async callTool(name, args, projectDir) {
    const localResult = await this.localToolSource.callTool(name, args, projectDir ?? this.projectDir);
    if (localResult !== undefined) {
      return localResult;
    }
    return this.session.execute(async (instance) => {
      const provider = this.providerFactory(instance.ipcEndpointName);
      return await provider.callTool(name, args, this.projectDir);
    }, { requiresProject: true, toolName: name });
  }
}

